-- Rifts World Book 21: Splynn Dimensional Market - its bestiary and its notable NPCs.
-- 0 creatures (migration 074) and 2 notable NPCs (migration 072),
-- with their attacks in stat_attacks (migration 073).
--
-- One-off data script, run once per environment. NOT a migration.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~378-splynn-npcs-e.sql
--
-- Written by scripts/bestiary-sql.mjs from 1 worker file(s). Every
-- creature row passes creatureFormulaGaps, every value is printable ASCII,
-- and an 8-word shingle check of the prose fields against the book's cached text finds no copied run.

INSERT INTO notable_npcs (slug, name, real_name, title, system, race, occ, level, alignment, age, height, weight, attributes, hp, sdc, mdc, ppe, isp, ar, horror_factor, combat, bonuses_note, skills, skills_note, natural_abilities, magic, psionics, super_powers, cybernetics, weapons_and_equipment, money, disposition, allies, enemies, description, source_book) VALUES
('miles-sky', 'Miles Sky', NULL, 'Co-owner of Skyborne Excursions', 'rifts', 'Kukulcan dragon, a hatchling, passing himself off as a D-Bee', '9th level Techno-Wizard Aviator (as printed; the class is from The Rifter #2, p.74, and has no class row here)', 9, 'Anarchist', NULL, NULL, NULL, '{"IQ":20,"ME":18,"MA":23,"PS":16,"PP":15,"PE":16,"PB":17,"Spd":14}', NULL, NULL, 300, 225, 58, NULL, 10, NULL, 'The block prints no attacks per melee and no combat bonuses, so none is stored and none is derived. Speed 14 running or 70 flying. Only printed attack damage is stored.', NULL, 'The block prints no skill list; none is supplied.', 'Nightvision to 100 feet (30.5 m), sharp hawk-like sight and the ability to see the invisible. Bio-regenerates 1D4x10 M.D.C. every five minutes, resists fire and cold, can change shape at will for up to 18 hours a day and can teleport himself at 44%. He can breathe out a poison vapor of 1D6 M.D., or 6D6 S.D.C. against a mortal victim. Vulnerabilities: none, the book says, beyond his growing greed.', 'Every Techno-Wizard Aviator ability at 9th level proficiency, plus all spell magic tied to air and flight; the block names no single spell and none is supplied. P.P.E. 225.', 'Sensitive powers: Empathy, Machine Ghost, Mind Block, Sense Evil, See Aura, Sixth Sense, Speed Reading, Telepathy and Total Recall. I.S.P. 58.', NULL, NULL, 'Usually a few Techno-Wizard devices on him. Favourite weapon: a TW Storm Staff, 6D6 M.D. by lightning bolts it throws or calls down from the sky (named as printed; the block does not show it to be the held Book of Magic Lightning Staff (Storm Staff), so it is not linked to that row; carried here, no gear row). His collection holds a Battle Fury Blade and a Deathbringer Sword (held catalog rows, Federation of Magic p.119-120), and he may carry nearly any magic item. Two Kittani ABS-3 Basic Security Drones, converted by Techno-Wizardry, go everywhere with him: they log his deals, keep him linked to the company''s main computer and defend him with built-in TW weapons (named here; no row of their own).', NULL, 'Far less noble than most of his kind and increasingly ruled by a dragon''s greed. Happy in his disguise and with the profits, but now weighing whether he could double them by pushing his partner out of the business.', 'Andruu Realm, his business partner, for now; his two converted Kittani security drones; the Kittani, whose vehicles and flight systems he sells in Splynn; the Minions of Splugorth, who back Skyborne and its owners.', NULL, 'Skyborne Excursions, which he founded with Andruu Realm, began as a little shop in the poor end of the Dimensional Market and now runs the city''s licensed tours, air taxis and rental craft and mounts, with outlets across Atlantis. Sky took up Techno-Wizardry when he was about fifty and turned it to aeronautics, a fit for a creature of the air. He brokered the deal that lets Skyborne sell Kittani craft in Splynn, and is quietly trying to sell flying platforms and perhaps Kittani vehicles to Tolkeen, held up because Tolkeen lacks the cash, he will not extend credit to a doomed nation, and Tolkeen will not take aid that traces back to the Splugorth. In disguise he is a good-looking D-Bee with very pale skin and dark blue eyes; his true form is a feathered serpent.', 'Rifts World Book 21: Splynn Dimensional Market p.173-176'),
('andruu-realm', 'Andruu Realm', NULL, 'Co-owner of Skyborne Excursions', 'rifts', 'Demigod, said to be the child of an alien Air Elemental god', '8th level demigod and Air Warlock (as printed)', 8, 'Miscreant', NULL, '8 feet (2.4 m)', NULL, '{"IQ":18,"ME":22,"MA":25,"PS":24,"PP":17,"PE":19,"PB":14,"Spd":13}', NULL, NULL, 186, 342, 86, NULL, 12, NULL, 'The block prints no attacks per melee and no combat bonuses, so none is stored and none is derived; each lightning blast costs one melee attack. Speed 13 running or 90 flying. Only printed attack damage is stored.', NULL, 'The block prints no skill list; none is supplied.', 'Sees the invisible; nightvision to 500 feet (152.4 m). Bio-regenerates 1D4x10 M.D.C. each hour, resists cold and is impervious to electricity and lightning. Throws lightning from his eyes and hands at no P.P.E. cost: 1D4x10+8 M.D., range 1000 feet (305 m), one melee attack per blast. Vulnerabilities: magic fire and M.D. plasma do him double damage.', 'All Air Elemental magic and abilities at 8th level proficiency, as an Air Warlock; the block names no single spell and none is supplied. P.P.E. 342.', 'Every Sensitive psionic power; the block lists none by name. I.S.P. 86.', NULL, NULL, 'Usually a light, decorative suit of magic armor of 125 M.D.C. and an Executioner''s Blade (named as printed; the block does not show it to be the held Corrupt Executioner''s Blade, so it is not linked to that row), though he mostly fights with his own powers. A few more magic weapons and a spare suit of armor are hidden away. A lesser Air Elemental hovers unseen near him at all times, and when he expects trouble he can call up two more lesser ones or a greater one within 1D4 minutes (named here; no row of their own). Armor, blade and elementals are carried here; no gear row.', 'A hidden ''small'' hoard worth 150 million credits; the book puts the two partners together at trillions or more.', 'Self-assured, magnetic and outwardly gentle; his deep, commanding voice makes him a superb salesman, and he flatters fearsome demon customers about how frightening they look on a flying mount. The friendliness is an act: he can turn cold and threatening in an instant. He suspects Sky means to buy him out and is untroubled, already thinking about where the traitor''s skull would hang.', 'Miles Sky, his partner, whom he no longer fully trusts; the Air Elementals who serve him; the Brodkil Empire, a trading partner; the Minions of Splugorth, who take the partners'' word over any outsider''s and come to their defense.', 'Miles Sky, should he move against him.', 'Skyborne Excursions, the air tour and transport company he co-owns with Miles Sky, holds Lord Splynncryth''s license for travel around Splynn and has grown into one of the city''s chief attractions. Realm led a small cult in another dimension until Sky offered him riches and the Megaverse; the two put in their money together and opened the business in Splynn. He won Skyborne a trade pact with the Brodkil Empire for weapons, bionics and vehicles, and is working on deals in Africa. He and Sky carry real weight with Splynn''s merchants and even the Minions. He looks like a heavily muscled, fair-haired human eight feet tall, apart from the ring of clouds that trails him and the crackle of electricity in his eyes.', 'Rifts World Book 21: Splynn Dimensional Market p.173-176');

INSERT INTO stat_attacks (owner_kind, owner_slug, name, damage, is_mega_damage, range, note, sort) VALUES
('notable_npc', 'miles-sky', 'TW Storm Staff (lightning bolt)', '6D6', 1, NULL, 'Bolts projected from the staff or called down from the sky.', 0),
('notable_npc', 'miles-sky', 'Poison vapor breath', '1D6', 1, NULL, 'Or 6D6 S.D.C., depending on the nature of the victim.', 1),
('notable_npc', 'andruu-realm', 'Lightning blast (eyes or hands)', '1D4x10+8', 1, '1000 feet (305 m)', 'No P.P.E. cost; each blast counts as one melee attack.', 0);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 notable NPCs are in' AS assertion, count(*) AS got, 2 AS want
  FROM notable_npcs WHERE slug IN ('miles-sky', 'andruu-realm');
SELECT 'and the notables 3' AS assertion, count(*) AS got, 3 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('miles-sky', 'andruu-realm');

